/* Explicit local batch downloads; existing review and per-load handlers remain authoritative. */
(() => {
  "use strict";
  const limit = 100;
  const hex = value => typeof value === "string" && /^[0-9a-f]{64}$/.test(value);
  window.createFreightBatchHandoff = getReviewState => {
    const chosen = new Map();
    let panel, summary, active = null, message = "Choose the saved reviews to keep together.";
    const same = (a, b) => a?.load_id === b?.load_id &&
      a?.evidence_version === b?.evidence_version && a?.review_version === b?.review_version;
    const current = id => ({
      load_id: id, evidence_version: summary?.evidence_versions?.[id],
      review_version: summary?.review_versions?.[id],
    });
    const dirty = () => {
      const state = getReviewState();
      const note = document.querySelector("#note");
      return !!note && note.value !== (state.summary?.decisions?.[state.selected]?.note || "");
    };
    const blocked = () => getReviewState().busy || dirty();
    const availableRows = () => {
      const rows = Array.isArray(summary?.packets) ? summary.packets : [];
      const counts = new Map();
      rows.forEach(row => counts.set(row.load_id, (counts.get(row.load_id) || 0) + 1));
      return rows.map(row => ({id: row.load_id, valid: typeof row.load_id === "string" &&
        row.load_id.length > 0 && counts.get(row.load_id) === 1 &&
        hex(current(row.load_id).evidence_version) && hex(current(row.load_id).review_version)}));
    };
    const selection = () => availableRows().filter(row => chosen.has(row.id))
      .map(row => ({...chosen.get(row.id)}));
    const updateControls = () => {
      if (!panel) return;
      const busy = blocked();
      panel.querySelector("[data-batch-download]").disabled = !chosen.size || busy || !!active;
      panel.querySelector("[data-batch-cancel]").hidden = !active;
      panel.querySelector("[data-batch-clear]").disabled = !chosen.size;
      const available = availableRows().filter(row => row.valid);
      panel.querySelector("[data-batch-all]").disabled = !available.length || available.length > limit;
      panel.querySelector("[data-batch-count]").textContent = chosen.size + " selected";
      panel.querySelector("[data-batch-status]").textContent = dirty()
        ? "Save or undo the current note edits before downloading saved reviews."
        : getReviewState().busy ? "Wait for the current review or pipeline update to finish." : message;
      panel.querySelectorAll("input[data-batch-load]").forEach(input => {
        input.checked = chosen.has(input.dataset.batchLoad);
      });
    };
    const cancel = text => {
      active?.controller.abort();
      active = null;
      if (text) message = text;
      updateControls();
    };
    const changedSelection = () => cancel("Selection updated. The archive will include only these saved reviews.");

    const download = async () => {
      if (!chosen.size || blocked() || active) { updateControls(); return; }
      const loads = selection();
      const ticket = {controller: new AbortController()};
      active = ticket;
      message = "Preparing the selected saved reviews…";
      updateControls();
      const stillCurrent = () => {
        const now = selection();
        return active === ticket && !ticket.controller.signal.aborted && !blocked() &&
          now.length === loads.length && now.every((row, i) => same(row, loads[i]));
      };
      let objectUrl, link;
      try {
        const response = await fetch("/api/review-batch", {
          method: "POST", headers: {"Content-Type": "application/json"},
          body: JSON.stringify({loads}), signal: ticket.controller.signal,
        });
        if (!response.ok) {
          const text = await response.text();
          let detail = text;
          try { detail = JSON.parse(text).error || text; } catch (_) {}
          throw new Error(detail || "The selected reviews could not be downloaded.");
        }
        const blob = await response.blob();
        if (!stillCurrent()) return;
        if (response.headers.get("Content-Type")?.split(";")[0] !== "application/zip") {
          throw new Error("The server did not return a batch review archive.");
        }
        const filename = /filename="([A-Za-z0-9_.-]+\.zip)"/.exec(
          response.headers.get("Content-Disposition") || "")?.[1];
        if (!filename) throw new Error("The batch archive has no download filename.");
        objectUrl = URL.createObjectURL(blob);
        link = document.createElement("a");
        link.href = objectUrl;
        link.download = filename;
        document.body.append(link);
        link.click();
        message = "Selected reviews downloaded. Unzip the file and open index.html.";
      } catch (error) {
        if (active === ticket) message = ticket.controller.signal.aborted
          ? "Batch download canceled. Saved reviews are unchanged."
          : error.message + " No batch was downloaded. Reload to inspect the current records before trying again.";
      } finally {
        link?.remove();
        if (objectUrl) setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);
        if (active === ticket) {
          active = null;
          updateControls();
        }
      }
    };

    document.addEventListener("input", event => {
      if (event.target.id === "note") {
        cancel(dirty() ? "Save or undo the current note edits before downloading saved reviews."
          : "The archive includes saved reviews only.");
      }
    });
    document.addEventListener("click", event => {
      if (event.target.closest("#run, #gen, button[data-d]")) {
        cancel("Review or pipeline update requested. The selected identities will be checked again.");
      }
    }, true);
    // Bubble after the existing target handler has set reviewBusy or disabled its button.
    document.addEventListener("click", event => {
      if (event.target.closest("#run, #gen, button[data-d]")) updateControls();
    });
    const observer = new MutationObserver(updateControls);
    ["run", "gen"].forEach(id => {
      const button = document.getElementById(id);
      if (button) observer.observe(button, {attributes: true, attributeFilter: ["disabled"]});
    });

    return {
      render(next, host) {
        summary = next;
        const rows = availableRows();
        const currentIds = new Set(rows.filter(row => row.valid).map(row => row.id));
        if ([...chosen].some(([id, old]) => !currentIds.has(id) || !same(old, current(id)))) {
          chosen.clear();
          cancel("Selection cleared because a selected packet or saved review changed. Inspect and select the current records again.");
        }
        if (!document.getElementById("freight-batch-style")) {
          const style = document.createElement("style");
          style.id = "freight-batch-style";
          style.textContent = "#freight-batch-panel{margin:1.2rem 0;padding:1rem;border:1px solid var(--line);background:white;border-radius:8px;min-width:0}" +
            "#freight-batch-panel legend{font-weight:700}#freight-batch-panel .batch-options{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,270px),1fr));gap:.4rem}" +
            "#freight-batch-panel label{display:flex;align-items:flex-start;gap:.5rem;min-height:44px;padding:.55rem;border:1px solid var(--line);border-radius:6px;overflow-wrap:anywhere}" +
            "#freight-batch-panel label span{min-width:0}#freight-batch-panel input{margin:.25rem .15rem 0 0;flex:none}" +
            "#freight-batch-panel .batch-actions{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem;margin:.8rem 0}" +
            "#freight-batch-panel button{min-height:44px;white-space:normal}#freight-batch-panel [role=status]{overflow-wrap:anywhere}";
          document.head.append(style);
        }
        panel = document.createElement("fieldset");
        panel.id = "freight-batch-panel";
        panel.innerHTML = '<legend>Download a group of saved reviews</legend>' +
          '<p>Choose up to 100 displayed loads. The archive keeps each original packet, saved review and history, with an index for the group. Unsaved notes are not included.</p>' +
          '<div class="batch-actions"><button type="button" data-batch-all>Select all available</button>' +
          '<button type="button" data-batch-clear>Clear selection</button><strong data-batch-count></strong></div>' +
          '<div class="batch-options"></div><div class="batch-actions">' +
          '<button type="button" class="pri" data-batch-download>Download selected reviews</button>' +
          '<button type="button" data-batch-cancel hidden>Cancel batch download</button></div>' +
          '<p data-batch-status role="status"></p><small>Draft snapshots only. Nothing is sent, invoiced or paid.</small>';
        const options = panel.querySelector(".batch-options");
        for (const row of rows) {
          const label = document.createElement("label");
          const input = document.createElement("input");
          input.type = "checkbox";
          input.dataset.batchLoad = row.id;
          input.disabled = !row.valid;
          const text = document.createElement("span");
          const review = summary?.decisions?.[row.id];
          const state = !row.valid ? "unavailable or ambiguous"
            : !review ? "not reviewed" : review.review_state === "current"
            ? "current saved review: " + review.decision : review.review_state + " saved review";
          text.textContent = row.id + " — " + state;
          input.addEventListener("change", () => {
            if (input.checked) {
              if (chosen.size >= limit) {
                input.checked = false;
                message = "Choose at most " + limit + " saved reviews.";
                updateControls();
                return;
              }
              chosen.set(row.id, current(row.id));
            } else chosen.delete(row.id);
            changedSelection();
          });
          label.append(input, text);
          options.append(label);
        }
        if (!rows.length) options.textContent = "No generated packets are available.";
        panel.querySelector("[data-batch-all]").onclick = () => {
          chosen.clear();
          rows.filter(row => row.valid).forEach(row => chosen.set(row.id, current(row.id)));
          changedSelection();
        };
        panel.querySelector("[data-batch-clear]").onclick = () => {
          chosen.clear();
          changedSelection();
        };
        panel.querySelector("[data-batch-download]").onclick = download;
        panel.querySelector("[data-batch-cancel]").onclick = () => cancel("Batch download canceled. Saved reviews are unchanged.");
        host.append(panel);
        updateControls();
      },
    };
  };
})();

"""Carrier fines matrix + settlement worksheet (brokered loads).

Brokers that run outside carriers typically publish a carrier fines schedule
(missing compliance photos, late POD, tracking not maintained, late
pickup/delivery) and give carriers a fixed dispute window. This module:

  * assesses fines ONLY from evidence on file (tracking stop events, the
    document log, the detention engine's late-arrival findings);
  * never guesses: if the evidence needed to judge a rule is missing
    (e.g. final departure unknown, so POD lateness can't be measured) the
    load goes to the exception queue instead of being fined;
  * tracks disputes against a dispute window (default 7 days from notice);
    a fine disputed inside the window is held, not deducted;
  * builds a settlement worksheet per carrier invoice: approved amount
    (capped at rate-con / telematics-supported values), fines deducted,
    net payable, and READY / HOLD for finance and factoring.

Inputs (all optional; no fines_schedule.csv = module is skipped):
  fines_schedule.csv   code,description,amount,applies_to
  documents.csv        load_id,doc_type,received_at      (POD, PICKUP_PHOTOS, DELIVERY_PHOTOS)
  disputes.csv         load_id,fine_code,received_at,reason
"""
from __future__ import annotations

import csv
import hashlib
from collections import defaultdict
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from pathlib import Path

from .detention import StopResult
from .ingest import dollars_to_cents, parse_time
from .invoice_match import Flag
from .models import Invoice, Load, RateCon

POD_DEADLINE = timedelta(hours=48)
DISPUTE_WINDOW = timedelta(days=7)
PHOTO_RULES = {"MISSING_PICKUP_PHOTOS": "PICKUP_PHOTOS", "MISSING_DELIVERY_PHOTOS": "DELIVERY_PHOTOS"}


@dataclass
class Fine:
    load_id: str
    carrier: str
    code: str
    amount_cents: int
    detail: str
    notice_date: str = ""
    dispute_deadline: str = ""
    status: str = "assessed"      # assessed | disputed_in_window | dispute_late
    dispute_note: str = ""
    evidence: list[str] = field(default_factory=list)

    @property
    def fine_id(self) -> str:
        raw = f"{self.load_id}|{self.code}|{self.amount_cents}|{'|'.join(self.evidence)}"
        return "FINE-" + hashlib.sha256(raw.encode()).hexdigest()[:10].upper()

    @property
    def deducted_cents(self) -> int:
        return 0 if self.status == "disputed_in_window" else self.amount_cents


def load_schedule(path: Path) -> dict[str, dict]:
    out = {}
    with Path(path).open(newline="", encoding="utf-8-sig") as fh:
        for i, r in enumerate(csv.DictReader(fh), start=2):
            out[r["code"].strip().upper()] = {
                "description": r.get("description", "").strip(),
                "amount_cents": dollars_to_cents(r["amount"]),
                "applies_to": (r.get("applies_to") or "brokered").strip().lower(),
                "source": f"{Path(path).name}:row{i}",
            }
    return out


def load_documents(path: Path) -> dict[str, dict[str, tuple[datetime, str]]]:
    """load_id -> doc_type -> (earliest received_at, evidence pointer)."""
    docs: dict[str, dict[str, tuple[datetime, str]]] = defaultdict(dict)
    p = Path(path)
    if not p.exists():
        return docs
    with p.open(newline="", encoding="utf-8-sig") as fh:
        for i, r in enumerate(csv.DictReader(fh), start=2):
            lid, typ = r["load_id"].strip(), r["doc_type"].strip().upper()
            at = parse_time(r["received_at"])
            cur = docs[lid].get(typ)
            if cur is None or at < cur[0]:
                docs[lid][typ] = (at, f"{p.name}:row{i}")
    return docs


def load_disputes(path: Path) -> dict[tuple[str, str], tuple[datetime, str, str]]:
    out = {}
    p = Path(path)
    if not p.exists():
        return out
    with p.open(newline="", encoding="utf-8-sig") as fh:
        for i, r in enumerate(csv.DictReader(fh), start=2):
            key = (r["load_id"].strip(), r["fine_code"].strip().upper())
            dispute = (parse_time(r["received_at"]), r.get("reason", "").strip(), f"{p.name}:row{i}")
            if key not in out or dispute[0] < out[key][0]:
                out[key] = dispute
    return out


def assess_fines(loads: dict[str, Load], stops_by_load: dict[str, list[StopResult]],
                 schedule: dict[str, dict], docs, disputes, invoices: list[Invoice],
                 has_documents: bool) -> tuple[list[Fine], list[dict]]:
    fines: list[Fine] = []
    exceptions: list[dict] = []
    notice_by_load = {}
    for inv in invoices:
        notice_by_load.setdefault(inv.load_id, inv.invoice_date)

    for lid, load in loads.items():
        rs = stops_by_load.get(lid, [])
        if not rs:
            continue
        if load.mode != "brokered":
            continue  # own fleet: driver compliance is an internal matter, not a carrier fine

        def add(code, detail, evidence):
            rule = schedule.get(code)
            if rule is None or rule["applies_to"] not in ("brokered", "all"):
                return
            fines.append(Fine(lid, load.carrier, code, rule["amount_cents"], detail,
                              evidence=[e for e in evidence if e] + [rule["source"]]))

        # Service failures, from the detention engine's findings.
        for r in rs:
            if r.status == "late_arrival":
                code = "LATE_PICKUP" if r.kind == "pickup" else "LATE_DELIVERY"
                add(code, f"stop {r.stop_index} {r.facility}: appointment {r.appointment:%Y-%m-%d %H:%M}, "
                          f"arrived {r.arrival:%Y-%m-%d %H:%M}", [r.arrival_src])
            elif r.status == "exception" and r.arrival is not None and r.departure is None:
                add("TRACKING_GAP", f"stop {r.stop_index} {r.facility}: tracking shows arrival but no "
                                    f"departure (tracking not maintained)", [r.arrival_src])

        if not has_documents:
            continue
        ldocs = docs.get(lid, {})
        for code, typ in PHOTO_RULES.items():
            if typ not in ldocs:
                add(code, f"no {typ.replace('_', ' ').lower()} on file", [f"documents.csv (no {typ} row)"])

        final = rs[-1]
        pod = ldocs.get("POD")
        if pod is not None:
            if final.departure is None:
                exceptions.append({"load_id": lid, "stop": final.stop_index,
                                   "reason": "POD timeliness not measurable: final departure unknown",
                                   "evidence": pod[1]})
            elif pod[0] - final.departure > POD_DEADLINE:
                hrs = (pod[0] - final.departure).total_seconds() / 3600
                add("LATE_POD", f"POD received {pod[0]:%Y-%m-%d %H:%M}, {hrs:.0f}h after final departure "
                                f"(limit {POD_DEADLINE.total_seconds() / 3600:.0f}h)",
                    [pod[1], final.departure_src])

    for f in fines:
        notice = notice_by_load.get(f.load_id)
        if notice:
            nd = parse_time(notice)
            f.notice_date = nd.strftime("%Y-%m-%d")
            f.dispute_deadline = (nd + DISPUTE_WINDOW).strftime("%Y-%m-%d")
        d = disputes.get((f.load_id, f.code))
        if d is not None:
            at, reason, src = d
            f.evidence.append(src)
            if f.dispute_deadline and at.date() <= parse_time(f.dispute_deadline).date():
                f.status = "disputed_in_window"
                f.dispute_note = f"disputed {at:%Y-%m-%d} (inside window): {reason}; held pending review"
            else:
                f.status = "dispute_late"
                f.dispute_note = f"disputed {at:%Y-%m-%d} after window closed {f.dispute_deadline}: {reason}"
    fines.sort(key=lambda f: (f.load_id, f.code))
    return fines, exceptions


@dataclass
class Settlement:
    invoice_no: str
    load_id: str
    carrier: str
    invoiced_cents: int
    approved_cents: int
    fines_cents: int
    net_cents: int
    status: str                 # READY | HOLD
    hold_reasons: list[str] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)
    evidence: list[str] = field(default_factory=list)


def settle(invoices: list[Invoice], loads: dict[str, Load], ratecons: dict[str, RateCon],
           supported: dict[str, int], flags: list[Flag], fines: list[Fine],
           stops_by_load: dict[str, list[StopResult]]) -> list[Settlement]:
    dup = {(f.invoice_no, f.load_id) for f in flags if f.code == "DUPLICATE_INVOICE"}
    fines_by_load = defaultdict(list)
    for f in fines:
        fines_by_load[f.load_id].append(f)
    out = []
    for inv in invoices:
        load, rc = loads.get(inv.load_id), ratecons.get(inv.load_id)
        by_code = defaultdict(int)
        for ln in inv.lines:
            by_code[ln.code] += ln.amount_cents
        invoiced = sum(by_code.values())
        holds, notes = [], []
        approved = 0
        if rc is None:
            holds.append("NO_RATECON")
        elif rc.parse_warnings:
            holds.append("RATECON_PARSE_WARNING")
        else:
            approved += min(by_code.get("LINEHAUL", 0), rc.linehaul_cents)
            approved += min(by_code.get("FUEL", 0), rc.fuel_cents)
            approved += min(by_code.get("DETENTION", 0), supported.get(inv.load_id, 0))
            for code, amt in by_code.items():
                if code not in ("LINEHAUL", "FUEL", "DETENTION"):
                    approved += min(amt, rc.accessorials_cents.get(code, 0))
        if (inv.invoice_no, inv.load_id) in dup:
            holds.append("DUPLICATE_INVOICE")
            approved = 0
        if load is not None and not load.pod_received:
            holds.append("MISSING_POD")
        if by_code.get("DETENTION") and any(r.status == "exception" for r in stops_by_load.get(inv.load_id, [])):
            holds.append("DETENTION_PENDING_REVIEW")
        if inv.total_cents != invoiced:
            notes.append("header total differs from line sum; settled on lines")
        lf = [] if "DUPLICATE_INVOICE" in holds else fines_by_load.get(inv.load_id, [])
        fines_cents = sum(f.deducted_cents for f in lf)
        for f in lf:
            if f.status == "disputed_in_window":
                notes.append(f"{f.code} {f.fine_id} disputed in window: not deducted")
        if approved < invoiced and "DUPLICATE_INVOICE" not in holds:
            notes.append(f"short-pay vs invoice: see invoice flags")
        out.append(Settlement(inv.invoice_no, inv.load_id, inv.carrier, invoiced, approved, fines_cents,
                              approved - fines_cents, "HOLD" if holds else "READY", holds, notes,
                              [inv.source_row] + ([rc.source] if rc else [])))
    out.sort(key=lambda s: (s.load_id, s.invoice_no))
    return out

"""Portable, read-only handoff for one generated freight packet and saved review."""
from __future__ import annotations

import hashlib
import io
import json
import re
import zipfile
from html import escape


def _json_bytes(value) -> bytes:
    # Escaped JSON preserves every saved string, including a legacy surrogate.
    return (json.dumps(value, sort_keys=True, indent=2, ensure_ascii=True,
                       allow_nan=False) + "\n").encode("utf-8")


def review_version(review) -> str:
    """Identity of the exact displayed native decision view, including history."""
    encoded = json.dumps(review, sort_keys=True, separators=(",", ":"),
                         ensure_ascii=True, allow_nan=False).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def bundle_filename(load_id: str, evidence_version: str) -> str:
    label = re.sub(r"[^A-Za-z0-9_-]+", "-", load_id).strip("-")[:64] or "load"
    return f"freight-review-{label}-{evidence_version[:12]}.zip"


def _text(value) -> str:
    text = str(value if value is not None else "").encode("utf-8", errors="backslashreplace").decode("utf-8")
    return escape(text, quote=True)


def _review_heading(review) -> str:
    if review is None:
        return "Not reviewed"
    state = review.get("review_state")
    if state == "cleared":
        return "Saved review cleared"
    if state == "current" and review.get("decision") in {"approve", "adjust", "reject"}:
        return "Current saved review: " + {"approve": "Approve", "adjust": "Needs adjust",
                                          "reject": "Reject"}[review["decision"]]
    return {"stale": "Previous review — review again",
            "unbound": "Previous review has no evidence binding — review again",
            "missing": "Previous review has no readable packet"}.get(
                state, "Unrecognized saved review — review again")


def _cover(load_id, evidence_version, saved_version, evidence, review) -> bytes:
    history = review.get("history", []) if review else []
    if not isinstance(history, list) or any(not isinstance(row, dict) for row in history):
        raise ValueError("saved review history is not a list of review records")
    details = ""
    if review:
        details = (f"<p>Recorded decision: <strong>{_text(review.get('decision'))}</strong>"
                   f"<br>Recorded at: {_text(review.get('at'))}</p>"
                   f"<h3>Saved note</h3><p class=\"note\">{_text(review.get('note')) or 'No saved note.'}</p>")
    previous = "".join(
        f"<li><strong>{_text(row.get('decision'))}</strong> · {_text(row.get('at'))}"
        f"<p class=\"note\">{_text(row.get('note'))}</p>"
        f"<small>Recorded evidence: {_text(row.get('evidence_version')) or 'Not recorded'}</small></li>"
        for row in reversed(history))
    section_counts = "".join(f"<li>{_text(name)}: {len(rows)} selected-load record(s)</li>"
                             for name, rows in evidence.items() if isinstance(rows, list))
    html = f"""<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Freight review handoff — {_text(load_id)}</title>
<style>
body{{font:16px/1.5 system-ui,sans-serif;max-width:850px;margin:2rem auto;padding:0 1rem;color:#1b1f24}}
h1{{font-size:1.7rem}}h2{{font-size:1.25rem}}.draft{{background:#fff4ce;border:1px solid #d8a800;padding:1rem}}
.note{{white-space:pre-wrap;overflow-wrap:anywhere}}code,small{{overflow-wrap:anywhere}}li{{margin:.6rem 0}}
@media print{{body{{margin:0}}a{{color:inherit}}}}
</style>
<h1>Freight review handoff</h1><h2>Load {_text(load_id)}</h2>
<p class="draft"><strong>Draft review.</strong> Nothing is sent, filed, invoiced or paid.
A reviewer decision is not a payment instruction.</p>
<h2>{_text(_review_heading(review))}</h2>
{details}
<p>The saved review and its history below are copied from the local review record.
An earlier or unbound review does not become approval of this packet.</p>
<h2>Open the evidence</h2>
<ul><li><a href="packet.html">Original generated packet</a></li>
<li><a href="evidence.json">Selected-load report records and original source references</a></li>
<li><a href="review.json">Exact saved review and history</a></li>
<li><a href="manifest.json">File sizes and SHA-256 checksums</a></li></ul>
